use std::fs;

use serde_json::json;

use super::tests::Fixture;
use super::{Profile, convert, json_bytes, model::Candidate, run, trust};
use crate::raw_source::sha256_hex;

fn fixture() -> Fixture {
    // Source projections come from the independently reviewed Python producer's
    // synthetic tests. They are not generated by the Rust code under test.
    let bundle = trust::strict_json(include_bytes!(
        "../../tests/fixtures/native-facts/items-actors-bc-synthetic.json"
    ))
    .unwrap();
    let mut f = Fixture::new();
    f.manifest = bundle["manifest"].clone();
    f.documents = bundle["documents"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(name, value)| (name.clone(), value.clone()))
        .collect();
    for (table, source) in bundle["tables"].as_object().unwrap() {
        let fields = source["fields"].as_array().unwrap();
        let rows = source["rows"].as_array().unwrap();
        f.documents.insert(format!("tables/{table}.json"), json!({
            "table":table,"raw_resource":format!("Data/Balance/{table}.datc64"),"row_key":"Logical synthetic source row",
            "physical_fields":fields,"columns":fields.iter().enumerate().map(|(index,field)| json!({
                "source_column":index,"schema":{"name":field},"physical_fields":[field]})).collect::<Vec<_>>(),
            "validation":{"rows":rows.len(),"schema_row_bytes":1,"actual_row_bytes":if rows.is_empty(){0}else{1},"warnings":[]},
            "rows":rows.iter().enumerate().map(|(index,value)|json!({"_row":index,"values":value})).collect::<Vec<_>>()
        }));
    }
    let lock = json_bytes(&f.documents["source-lock.json"]).unwrap();
    assert_eq!(
        sha256_hex(&lock),
        f.manifest["source_identity"]["source_lock_sha256"]
    );
    fs::write(f.root.join("source-lock.json"), lock).unwrap();
    f.seal();
    f
}

fn args(f: &Fixture, output: &str) -> super::Args {
    let mut args = f.args(output);
    args.profile = Profile::ItemsActorsBc;
    args
}

fn rejects(f: &Fixture, expected: &str) {
    let error = run(args(f, "bad-output")).unwrap_err();
    assert!(
        error.contains(expected),
        "expected {expected:?}, got {error:?}"
    );
    assert!(
        !f.root.join("bad-output").exists(),
        "invalid B/C input created output"
    );
}

#[test]
fn preserves_eight_slots_native_owners_and_separate_actor_identity() {
    let f = fixture();
    let c = convert::normalize(&trust::verify(&args(&f, "unused")).unwrap()).unwrap();
    assert_eq!(c.format, "pobr-native-domain-candidate/v4");
    let items = c.items.as_ref().unwrap();
    assert_eq!(items.mods[0].slots.len(), 8);
    assert_eq!(items.mods[0].slots[7].max_hardmode_raw, 24);
    assert!(items.mods[0].slots[1].stat.is_none());
    assert_eq!(
        items.mods[0].families[0]
            .target
            .as_ref()
            .unwrap()
            .id
            .as_deref(),
        Some("second")
    );
    assert_eq!(
        items.base_items[1].charges.as_ref().unwrap().values_raw["PerCharge2"],
        0
    );
    assert!(items.base_items[0].charges.is_none());
    assert!(items.soul_cores[0].stat_groups[0].regular.is_empty());
    assert_eq!(
        items.soul_cores[0].stat_groups[0].bonded[1]
            .value_raw
            .as_i64(),
        Some(-7)
    );
    assert!(items.soul_core_categories[0].target_item_classes.is_empty());
    assert_eq!(items.soul_core_categories[0].unknown0_raw.as_u64(), Some(8));
    assert_eq!(
        items.utility_buffs[0].primary[0].value_raw.as_i64(),
        Some(25)
    );
    assert!(items.utility_buffs[0].secondary_values_raw.is_empty());
    assert_eq!(
        items.utility_buffs[0].granted_flags[0]
            .target
            .as_ref()
            .unwrap()
            .raw
            .payload,
        "tables/Stats.json"
    );
    assert!(items.essence_mods[0].outcomes.is_none());
    assert_eq!(items.essence_mods[0].outcome_mods.len(), 2);
    let actors = c.actors.as_ref().unwrap();
    assert_eq!(
        actors.constants[0].constant.id.as_deref(),
        Some("Whitespace ")
    );
    assert_eq!(actors.default_monster_stats.len(), 100);
    assert_eq!(
        actors.default_monster_stats[0].values_raw["MinionDamage"]
            .as_f64()
            .unwrap()
            .to_bits(),
        (-0.0_f64).to_bits()
    );
    assert_eq!(
        actors.summoned_specific_monsters[0].id_raw.as_i64(),
        Some(17)
    );
    assert!(actors.summoned_specific_monsters[0].monster.is_none());
    assert_eq!(
        actors.summoned_specific_monsters[1]
            .monster
            .as_ref()
            .unwrap()
            .id
            .as_deref(),
        Some("monster")
    );
    assert!(actors.auxiliary_rows["DisplayMinionMonsterType"].is_empty());
    let reread: Candidate = serde_json::from_slice(&json_bytes(&c).unwrap()).unwrap();
    assert_eq!(reread.items_actors_summary.unwrap().mod_rows, 1);
    run(args(&f, "a")).unwrap();
    run(args(&f, "b")).unwrap();
    for name in [
        "candidate.json",
        "candidate-receipt.json",
        "source-manifest.json",
        "source-lock.json",
        "source-diagnostics.json",
    ] {
        assert_eq!(
            fs::read(f.root.join("a").join(name)).unwrap(),
            fs::read(f.root.join("b").join(name)).unwrap()
        );
    }
}

#[test]
fn rejects_resealed_bc_projection_corruption() {
    for (name, pointer, value) in [
        ("items.json", "/mods/0/slots/7/max_raw", json!(99)),
        ("items.json", "/mods/0/families", json!([])),
        (
            "items.json",
            "/base_items/1/charges/values_raw/PerCharge2",
            json!(7),
        ),
        (
            "items.json",
            "/soul_cores/0/stat_groups/0/bonded",
            json!([]),
        ),
        (
            "items.json",
            "/soul_core_categories/0/unknown0_raw",
            json!(0),
        ),
        ("items.json", "/utility_buffs/0/granted_flags", json!([])),
        ("items.json", "/essence_mods/0/outcomes", json!([])),
        (
            "actors.json",
            "/constants/0/constant/id",
            json!("Whitespace"),
        ),
        (
            "actors.json",
            "/default_monster_stats/0/values_raw/MinionDamage",
            json!(0.0),
        ),
        (
            "actors.json",
            "/summoned_specific_monsters/0/id_raw",
            json!("17"),
        ),
        ("actors.json", "/monsters/0/granted_effects", json!([])),
    ] {
        let mut f = fixture();
        *f.documents
            .get_mut(name)
            .unwrap()
            .pointer_mut(pointer)
            .unwrap() = value;
        f.seal();
        rejects(&f, "items/actors physical projection mismatch");
    }
}

#[test]
fn rejects_bc_owner_ambiguity_required_pairs_and_orphans() {
    for (table, field, value, message) in [
        ("Mods", "Stat8", json!(99), "unresolved physical row"),
        (
            "Mods",
            "SpawnWeight_Values",
            json!([]),
            "unequal required reference/value arrays",
        ),
        (
            "ComponentCharges",
            "BaseItemTypesKey",
            json!("Shared name"),
            "unresolved or ambiguous charge",
        ),
        (
            "SoulCoreStats",
            "SoulCore",
            json!(99),
            "unresolved physical row",
        ),
        (
            "SoulCoreStats",
            "BondedStatsValues",
            json!([]),
            "unequal required reference/value arrays",
        ),
        (
            "UtilityFlaskBuffs",
            "StatValues",
            json!([]),
            "unequal required reference/value arrays",
        ),
        (
            "GameConstants",
            "Divisor",
            json!(0),
            "zero constant divisor",
        ),
        (
            "DefaultMonsterStats",
            "DisplayLevel",
            json!("2"),
            "invalid default monster level order",
        ),
        (
            "SummonedSpecificMonsters",
            "MonsterVarietiesKey",
            json!(99),
            "unresolved physical row",
        ),
    ] {
        let mut f = fixture();
        f.documents
            .get_mut(&format!("tables/{table}.json"))
            .unwrap()["rows"][0]["values"][field] = value;
        f.seal();
        rejects(&f, message);
    }
    let mut f = fixture();
    let doc = f.documents.get_mut("tables/ArmourTypes.json").unwrap();
    let mut duplicate = doc["rows"][0].clone();
    duplicate["_row"] = 1.into();
    doc["rows"].as_array_mut().unwrap().push(duplicate);
    doc["validation"]["rows"] = 2.into();
    f.seal();
    rejects(&f, "ambiguous component owner");
    let mut f = fixture();
    let doc = f.documents.get_mut("tables/SoulCores.json").unwrap();
    doc["rows"] = json!([]);
    doc["validation"]["rows"] = 0.into();
    doc["validation"]["actual_row_bytes"] = 0.into();
    f.seal();
    rejects(&f, "unresolved physical row");
}

#[test]
fn numeric_ids_and_zero_row_width_have_bounded_profile_semantics() {
    let mut f = fixture();
    f.documents
        .get_mut("tables/SummonedSpecificMonsters.json")
        .unwrap()["rows"][1]["values"]["Id"] = 17.into();
    f.documents.get_mut("actors.json").unwrap()["summoned_specific_monsters"][1]["id_raw"] =
        17.into();
    f.seal();
    run(args(&f, "duplicate-numeric-id")).unwrap();
    for bad in [json!("17"), json!(17.0), json!(true)] {
        let mut f = fixture();
        f.documents
            .get_mut("tables/SummonedSpecificMonsters.json")
            .unwrap()["rows"][0]["values"]["Id"] = bad;
        f.seal();
        rejects(&f, "invalid numeric summoned-monster Id");
    }
    let mut f = fixture();
    f.documents
        .get_mut("tables/DisplayMinionMonsterType.json")
        .unwrap()["validation"]["actual_row_bytes"] = 1.into();
    f.seal();
    rejects(&f, "physical table validation failed");
    let mut f = fixture();
    f.documents.get_mut("tables/Stats.json").unwrap()["rows"][0]["values"]["Id"] = 17.into();
    f.seal();
    rejects(&f, "expected stable string id");
}

#[test]
fn bc_keeps_explicit_profile_and_exact_producer_inventory() {
    let f = fixture();
    assert!(run(f.args("base")).is_err());
    for profile in [Profile::CoreSkillsA0, Profile::GemsConstraintsA1] {
        let mut args = args(&f, "older");
        args.profile = profile;
        assert!(run(args).is_err());
    }
    for key in [
        "RePoE/native_items.py",
        "RePoE/native_actor_facts.py",
        "RePoE/native_facts.py",
    ] {
        let mut f = fixture();
        f.manifest["producer"][key] = "0".repeat(64).into();
        f.seal();
        rejects(&f, "producer identity mismatch");
    }
    let parsed=super::parse_args("--native-facts in --expected-manifest-sha256 h --source-lock lock --out out --profile items-actors-bc".split_whitespace().map(String::from)).unwrap();
    assert_eq!(parsed.profile, Profile::ItemsActorsBc);
}
